def _shuf(qs):
    import random
    r = random.Random(77)
    out = []
    for t in qs:
        o = list(t[2]); c = o[t[3]]
        r.shuffle(o)
        out.append((t[0], t[1], o, o.index(c), t[4], t[5], t[6]))
    return out
QS = _shuf(QS)
